<script>
  (function () {
    var photoInput = document.getElementById('photoInput');
    var exportButton = document.getElementById('exportButton');
    var page = document.getElementById('page');
    var currentPhoto = null;

    document.querySelectorAll('.photo').forEach(function (photo) {
      photo.addEventListener('click', function () {
        currentPhoto = photo;
        photoInput.value = '';
        photoInput.click();
      });
    });

    photoInput.addEventListener('change', function () {
      var file = photoInput.files && photoInput.files[0];
      if (!file || !currentPhoto) return;
      var target = currentPhoto;
      var reader = new FileReader();
      reader.onload = function () {
        var img = target.querySelector('img');
        if (!img) {
          img = document.createElement('img');
          img.alt = '';
          target.appendChild(img);
        }
        img.src = reader.result;
        target.classList.add('has-image');
      };
      reader.readAsDataURL(file);
    });

    exportButton.addEventListener('click', function () {
      if (typeof htmlToImage === 'undefined') {
        alert('이미지 변환 라이브러리를 불러오지 못했습니다. 인터넷 연결을 확인해 주세요.');
        return;
      }
      exportButton.disabled = true;
      exportButton.textContent = '저장하는 중…';

      var fontsReady = document.fonts && document.fonts.ready ? document.fonts.ready : Promise.resolve();

      fontsReady
        .then(function () {
          return htmlToImage.toBlob(page, {
            pixelRatio: 1,
            width: 860,
            height: page.scrollHeight,
            backgroundColor: '#FFFFFF',
            style: { margin: '0' },
            filter: function (node) {
              return !(node.hasAttribute && node.hasAttribute('data-noexport'));
            }
          });
        })
        .then(function (blob) {
          var url = URL.createObjectURL(blob);
          var link = document.createElement('a');
          link.href = url;
          link.download = 'detail.png';
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
        })
        .catch(function (error) {
          console.error(error);
          alert('이미지 저장에 실패했습니다.');
        })
        .then(function () {
          exportButton.disabled = false;
          exportButton.textContent = '이미지로 저장';
        });
    });
  })();
